lua local Players = game:GetService("Players") local player = Players.LocalPlayer  local gui = Instance.new("ScreenGui") gui.Name = "DELTA_HUB" gui.ResetOnSpawn = false gui.Parent = player:WaitForChild("PlayerGui")  local main = Instance.new("Frame") main.Size = UDim2.fromOffset(300, 270) main.Position = UDim2.new(0.5, -150, 0.5, -135) main.BackgroundColor3 = Color3.fromRGB(15, 10, 25) main.Active = true main.Draggable = true main.Parent = gui  Instance.new("UICorner", main).CornerRadius =     UDim.new(0, 15)  local stroke = Instance.new("UIStroke", main) stroke.Color = Color3.fromRGB(170, 0, 255) stroke.Thickness = 2  local title = Instance.new("TextLabel") title.Size = UDim2.new(1, 0, 0, 50) title.BackgroundTransparency = 1 title.Text = "✦ DELTA HUB ✦" title.TextColor3 = Color3.fromRGB(210, 130, 255) title.TextSize = 24 title.Font = Enum.Font.GothamBold title.Parent = main  local function createButton(name, y)     local button = Instance.new("TextButton")     button.Size = UDim2.new(0.85, 0, 0, 42)     button.Position = UDim2.new(0.075, 0, 0, y)     button.BackgroundColor3 = Color3.fromRGB(55, 20, 85)     button.Text = name .. " : OFF"     button.TextColor3 = Color3.new(1, 1, 1)     button.TextSize = 15     button.Font = Enum.Font.GothamBold     button.Parent = main      Instance.new("UICorner", button).CornerRadius =         UDim.new(0, 9)      local enabled = false      button.Activated:Connect(function()         enabled = not enabled         button.Text = name .. (enabled and " : ON" or " : OFF")         button.BackgroundColor3 = enabled             and Color3.fromRGB(150, 40, 220)             or Color3.fromRGB(55, 20, 85)     end) end  createButton("SECRET EGG", 65) createButton("ETERNAL EGG", 115) createButton("DIVINE EGG", 165)  print("DELTA HUB LOADED") 
